def _make_voice(phase=0.0, phase_increment=0.1, attack_samples=100.0,
                release_samples=100.0, releasing_since=None, samples_rendered=0):
    """Build a _Voice without invoking any hardware-touching constructor path."""
    voice = _Voice.__new__(_Voice)
    voice._phase = phase
    voice._phase_increment = phase_increment
